package org.jlinalg.cli;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;

/** Admitted original model execution plus independent complete native result/state checks. */
final class ScviWorkflow {
    private ScviWorkflow() { }
    record Limits(ScviProcess.Limits process,ScviOutputAudit.Limits output,ScviModelBytes.Limits model,ScviModelMetadata.Limits metadata,long reportBytes,long retainedBytes) {
        Limits{Objects.requireNonNull(process);Objects.requireNonNull(output);Objects.requireNonNull(model);Objects.requireNonNull(metadata);if(reportBytes<1||reportBytes>67_108_864||retainedBytes<1)throw new IllegalArgumentException("Bounded complete workflow capacities required");}
        static Limits standard(){return new Limits(new ScviProcess.Limits(3600000,34_359_738_368L,3600,4_294_967_296L,512,17_179_869_184L,32768,8,64,8_589_934_592L,25),new ScviOutputAudit.Limits(4_294_967_296L,10_000_000,8192,1_048_576),ScviModelBytes.Limits.standard(),ScviModelMetadata.Limits.standard(),16_777_216,536_870_912);}
    }
    record Data(ScviMatrix.Prepared matrix,ScviCovariates.Prepared covariates,String layer,Map<String,List<String>> categoryOrder,ScviProjection.Prepared projection,Path wholeAnalysisRoot) {
        Data(ScviMatrix.Prepared matrix,ScviCovariates.Prepared covariates,String layer,Map<String,List<String>> categoryOrder,ScviProjection.Prepared projection){this(matrix,covariates,layer,categoryOrder,projection,null);}
        Data{Objects.requireNonNull(matrix);Objects.requireNonNull(covariates);var order=new TreeMap<String,List<String>>();categoryOrder.forEach((k,v)->order.put(k,List.copyOf(v)));categoryOrder=Collections.unmodifiableMap(order);}
        void verify(Runnable check)throws IOException{
            matrix.verify(check);covariates.verify(check);if(projection!=null)projection.verify(check);
            if(!matrix.cells().equals(covariates.matrix().cells())||matrix.request().kind()!=covariates.matrix().request().kind())throw new IOException("Workflow matrix/metadata complete population or kind differs");
            if(projection!=null&&matrix!=projection.reference()&&matrix!=projection.query())throw new IOException("Workflow matrix is not an admitted projection result");
            for(var e:categoryOrder.entrySet()){var observed=covariates.observedCategoryCounts().get(e.getKey());if(observed==null||new HashSet<>(e.getValue()).size()!=e.getValue().size()||!e.getValue().containsAll(observed.keySet()))throw new IOException("Reviewed category order does not cover its selected observed role");}
        }
        List<Path> roots(){var paths=new ArrayList<Path>(List.of(matrix.directory(),covariates.directory(),covariates.matrix().directory()));if(projection!=null){paths.add(projection.directory());for(var parent:projection.parents())paths.add(parent.directory());}return separate(paths);}
        Map<String,Object> protocol(ScviQueryBridge.Prepared bridge){var s=covariates.spec();var p=new TreeMap<String,Object>();p.put("matrix",matrix.directory());p.put("metadata",covariates.directory().resolve("metadata.tsv"));p.put("layer",bridge==null?layer:bridge.layer());p.put("batch",bridge==null?s.batch():bridge.batch());p.put("categorical",bridge==null?s.categorical():bridge.categorical());p.put("continuous",bridge==null?s.continuous():bridge.continuous());p.put("labels",bridge==null?s.labels():bridge.labels());p.put("unlabeled",s.unlabeledCategory());p.put("categorical_order",categoryOrder);p.put("query_bridge",bridge==null?null:bridge.protocol());return p;}
    }
    record Result(Path directory,ScviRuntime.Context runtime,Data data,ScviModelMetadata.Prepared metadata,List<Map<String,Object>> stages,Limits limits,ScviRuntime.Tree tree,ScviModelMetadata.Info reference) {
        Result{stages=List.copyOf(stages);}
        ScviModelMetadata.Info finalModel(){return metadata.models().get(metadata.models().size()-1);}
        void verify(Runnable check)throws IOException{runtime.verify(check);data.verify(check);metadata.verify(check);if(reference!=null)reference.verify(limits.metadata,check);if(!tree.equals(ScviRuntime.tree(directory,treeLimits(limits),check)))throw new IOException("Complete admitted workflow outputs or member population changed");}
    }
    static Result fit(ScviRuntime.Context runtime,Data data,ScviModelRequest.Fit fit,Path output,Limits limits,Runnable check)throws IOException{
        fit.validateMetadata(data.covariates.spec());if(data.matrix.request().kind()!=fit.inputReview().kind()||!fit.inputReview().suppliedLayer().equals(data.layer==null?"X":data.layer))throw new IOException("Reviewed fit kind/layer differs from the admitted input");
        if(fit.network() instanceof ScviModelRequest.SysviNetwork network)network.validatePopulation(data.matrix.cells().size());
        var names=fit.family()==ScviModelRequest.Family.SYSVI?List.of("fit"):fit.annotation()==null?List.of("base"):List.of("base","reference");
        var families=fit.family()==ScviModelRequest.Family.SYSVI?List.of(ScviModelRequest.Family.SYSVI):fit.annotation()==null?List.of(ScviModelRequest.Family.SCVI):List.of(ScviModelRequest.Family.SCVI,ScviModelRequest.Family.SCANVI);
        var trainings=fit.annotation()==null?List.of(fit.training()):List.of(fit.training(),fit.annotation().training());
        return execute(runtime,data,fit.release(),fit.protocol(),fit.network(),names,families,trainings,null,null,output,limits,check);
    }
    static Result query(ScviRuntime.Context runtime,Data data,ScviModelRequest.Query request,ScviModelMetadata.Info reference,ScviQueryBridge.Request bridgeRequest,Path output,Limits limits,Runnable check)throws IOException{
        reference.verify(limits.metadata,check);reference.requireFloat32Profile();if(reference.family()!=request.referenceFamily()||!reference.release().equals(request.release().version)||!reference.genes().equals(data.matrix.genes())||data.matrix.request().kind()!=request.inputReview().kind())throw new IOException("Reviewed fixed query/reference family,release,gene order or input kind differs");
        if(!data.categoryOrder.isEmpty())throw new IOException("Fixed query categories use the actual reference registry;no independent query category order may replace it");
        var bridge=ScviQueryBridge.prepare(data.covariates,data.layer==null?"X":data.layer,reference,bridgeRequest);
        return execute(runtime,data,request.release(),request.protocol(),null,List.of("query"),List.of(request.referenceFamily()),List.of(request.training()),reference,bridge,output,limits,check);
    }
    private static Result execute(ScviRuntime.Context runtime,Data data,ScviModelRequest.Release release,Map<String,Object> scientific,ScviModelRequest.Network network,List<String> names,List<ScviModelRequest.Family> families,List<ScviModelRequest.Training> trainings,ScviModelMetadata.Info reference,ScviQueryBridge.Prepared bridge,Path supplied,Limits limits,Runnable check)throws IOException{
        if(release!=ScviModelRequest.Release.V1_3_0)throw new ScviRuntime.Unavailable("Exact historical runtime unavailable;no release substitution. Required action: admit the required version or skip this analysis.");
        data.verify(check);runtime.verify(check);for(var t:trainings)validateTrainingPopulation(t,data.matrix.cells().size());
        Path out=supplied.toAbsolutePath().normalize();if(out.getParent()==null||!out.getParent().toRealPath().equals(out.getParent()))throw new IOException("Require a NEW canonical workflow directory");
        var roots=new ArrayList<Path>(data.roots());roots.add(runtime.home());if(reference!=null)roots.add(reference.model().directory());
        for(Path p:roots)if(out.startsWith(p)||p.startsWith(out))throw new IOException("Workflow output overlaps an admitted input/runtime/model");
        Files.createDirectory(out);Path prepared=Files.createDirectory(out.resolve("prepared"));Path script=prepared.resolve("scvi_model_run.py"),common=prepared.resolve("scvi_provider_common.py");
        Files.write(script,ScviRuntime.resource("/org/jlinalg/omics/scvi_model_run.py"),StandardOpenOption.CREATE_NEW);Files.write(common,ScviRuntime.resource("/org/jlinalg/omics/scvi_provider_common.py"),StandardOpenOption.CREATE_NEW);
        var protocol=new TreeMap<String,Object>();protocol.put("schema","omicsmatic-scvi-execution-v1");protocol.put("data",data.protocol(bridge));protocol.put("scientific",scientific);if(reference!=null)protocol.put("reference_directory",reference.model().directory());Path request=prepared.resolve("request.json");Files.writeString(request,ScviJson.json(protocol)+"\n",StandardOpenOption.CREATE_NEW);
        String scriptHash=ScviText.hash(script,1_048_576,check),commonHash=ScviText.hash(common,1_048_576,check),requestHash=ScviText.hash(request,limits.reportBytes,check);if(!commonHash.equals(runtime.commonSha256()))throw new IOException("Fixed provider/shared helper differs from live admitted runtime");
        ScviProcess.Check integrity=()->{data.verify(check);runtime.verify(check);if(reference!=null)reference.verify(limits.metadata,check);if(!ScviText.hash(script,1_048_576,check).equals(scriptHash)||!ScviText.hash(common,1_048_576,check).equals(commonHash)||!ScviText.hash(request,limits.reportBytes,check).equals(requestHash))throw new IOException("Fixed provider or closed execution request changed");};
        var accounted=new ArrayList<Path>(data.roots());accounted.add(prepared);if(reference!=null)accounted.add(reference.model().directory());accounted=new ArrayList<>(separate(accounted));
        ScviProcess.Limits processLimits=limits.process;
        if(data.wholeAnalysisRoot!=null){var scope=ScviAnalysisWorkspace.scopes(data.wholeAnalysisRoot,out.resolve("run"));accounted=new ArrayList<>(scope.directories());processLimits=scope.process(limits.process);Files.writeString(prepared.resolve("workspace-scope.json"),ScviJson.json(scope)+"\n",StandardOpenOption.CREATE_NEW);}
        ScviProcess.executeOwned(List.of(runtime.python().toString(),"-I","-B",script.toString(),request.toString(),out.resolve("run/result").toString()),ScviRuntime.environment(),out.resolve("run"),processLimits,integrity,check,accounted);integrity.verify();
        Path result=out.resolve("run/result");Map<?,?> report=object(parse(result.resolve("execution.json"),limits,check));
        if(!"completed-original-model-execution-native-audit-required".equals(report.get("status"))||!Boolean.FALSE.equals(report.get("model_analysis_completed"))||!requestHash.equals(report.get("scientific_request_sha256")))throw new IOException("Original model execution protocol/source differs");ScviRuntime.verifyExecution(runtime,report,out.resolve("run"),result,check);
        List<?> emitted=list(report.get("stages"));if(emitted.size()!=names.size())throw new IOException("Original complete model stage population differs");Path models=Files.createDirectory(out.resolve("reviewed-models"));var reviewed=new ArrayList<ScviModelBytes.Prepared>();var expected=new ArrayList<ScviModelMetadata.Expected>();
        for(int i=0;i<names.size();i++){String name=names.get(i);Map<?,?> stage=object(emitted.get(i));if(!name.equals(stage.get("name"))||!families.get(i).name().equals(stage.get("family"))||!Boolean.TRUE.equals(stage.get("strict_original_reload_completed"))||!data.matrix.cells().equals(stage.get("cells"))||!data.matrix.genes().equals(stage.get("genes")))throw new IOException("Original model stage family/cells/genes/strict reload differs");Path model=result.resolve(name+"-model/model.pt");String hash=ScviText.hash(model,limits.model.modelBytes(),check);if(!hash.equals(stage.get("model_sha256")))throw new IOException("Original self-created model hash differs");
            var review=new ScviModelBytes.Review("OmicsMatic fixed-provider current execution","Model self-created from admitted non-pickle data by this fixed original provider;script="+scriptHash+";request="+requestHash,"Permit original loading only of this exact current execution SHA256;no third-party model permission",hash,true);reviewed.add(ScviModelBytes.prepare(model,review,release,families.get(i),models.resolve(name),limits.model,check));expected.add(new ScviModelMetadata.Expected(true,data.matrix.genes(),network));}
        var metadata=ScviModelMetadata.inspect(runtime,reviewed,expected,out.resolve("model-inspection"),limits.metadata,check,data.wholeAnalysisRoot);var audits=new ArrayList<Map<String,Object>>();
        for(int i=0;i<names.size();i++){var model=metadata.models().get(i);model.requireFloat32Profile();if(model.registeredCells()!=data.matrix.cells().size())throw new IOException("Actual trained model registered cell population differs");var reported=new ArrayList<ScviModelMetadata.Scalar>();for(Object value:list(object(emitted.get(i)).get("classes"))){var scalar=object(value);reported.add(new ScviModelMetadata.Scalar((String)scalar.get("kind"),(String)scalar.get("value")));}if(!reported.equals(model.classes()))throw new IOException("Probability aliases differ from the actual saved-model learned class order/types");if(reference!=null)ScviQueryBridge.verifyTransferredRegistry(reference,model,bridge);audits.add(audit(result,names.get(i),data.matrix.cells(),model,trainings.get(i),limits.output,check));}
        integrity.verify();metadata.verify(check);ScviProcess.workspaceBytes(out,limits.process,data.roots());Files.writeString(out.resolve("workflow-admission.json"),ScviJson.json(Map.of("status","ADMITTED_ORIGINAL_MODEL_ANALYSIS","model_analysis_completed",true,"scientific_request_sha256",requestHash,"provider_sha256",scriptHash,"stages",audits,"warning","Synthetic validation does not establish biological accuracy,preprocessing correctness or convergence;inspect original warnings and input/conversion provenance."))+"\n",StandardOpenOption.CREATE_NEW);
        var tree=ScviRuntime.tree(out,treeLimits(limits),check);var admitted=new Result(out,runtime,data,metadata,audits,limits,tree,reference);admitted.verify(check);return admitted;
    }
    static Map<String,Object> audit(Path output,String name,List<String> cells,ScviModelMetadata.Info model,ScviModelRequest.Training training,ScviOutputAudit.Limits limits,Runnable check)throws IOException{
        var latent=ScviOutputAudit.latent(output.resolve(name+"-latent.tsv"),cells,model.latent(),limits,check);var reload=ScviOutputAudit.latent(output.resolve(name+"-reload-latent.tsv"),cells,model.latent(),limits,check);if(!latent.equals(reload))throw new IOException("Original strict saved-model reload changed complete latent float32 outputs");
        var split=ScviOutputAudit.splits(output.resolve(name+"-splits.tsv"),cells,limits,check);long train=(long)Math.ceil(training.trainFraction()*cells.size()),validation=training.validationFraction()==null?cells.size()-train:(long)Math.floor(training.validationFraction()*cells.size());if(split.train()!=train||split.validation()!=validation||split.test()!=cells.size()-train-validation)throw new IOException("Original training split differs from explicitly requested complete-population fractions");
        var history=ScviOutputAudit.history(output.resolve(name+"-history.tsv"),training.epochs(),limits,check);var audit=new TreeMap<String,Object>();audit.put("name",name);audit.put("family",model.family());audit.put("latent",latent);audit.put("splits",split);audit.put("history",history);audit.put("classes",model.classes().stream().map(ScviModelMetadata.Scalar::json).toList());
        if(model.family()==ScviModelRequest.Family.SCANVI){var aliases=new ArrayList<String>();for(int i=0;i<model.classes().size();i++)aliases.add("class_"+i);var classification=ScviOutputAudit.classification(output.resolve(name+"-probabilities.tsv"),output.resolve(name+"-labels.tsv"),cells,aliases,limits,check);var reloaded=ScviOutputAudit.classification(output.resolve(name+"-reload-probabilities.tsv"),output.resolve(name+"-labels.tsv"),cells,aliases,limits,check);if(!classification.equals(reloaded))throw new IOException("Original strict reload changed complete class probabilities");audit.put("classification",classification);}return Collections.unmodifiableMap(audit);
    }
    private static void validateTrainingPopulation(ScviModelRequest.Training t,int cells)throws IOException{long train=(long)Math.ceil(t.trainFraction()*cells),validation=t.validationFraction()==null?cells-train:(long)Math.floor(t.validationFraction()*cells);if(train<1||train+validation>cells||t.earlyStopping()!=null&&validation==0)throw new IOException("Requested complete-population training/validation split is empty or inconsistent");}
    private static ScviRuntime.Limits treeLimits(Limits l){return new ScviRuntime.Limits(l.process.workspaceBytes(),l.process.fileCount(),l.retainedBytes,l.reportBytes,l.process);}
    private static Object parse(Path p,Limits l,Runnable check)throws IOException{ScviText.hash(p,l.reportBytes,check);return SimpleJson.parse(Files.readString(p));}
    private static Map<?,?> object(Object x)throws IOException{if(x instanceof Map<?,?> map)return map;throw new IOException("Expected original workflow JSON object");}
    private static List<?> list(Object x)throws IOException{if(x instanceof List<?> list)return list;throw new IOException("Expected original workflow stage population");}
    private static List<Path> separate(List<Path> paths){var unique=new ArrayList<Path>(new LinkedHashSet<>(paths));unique.removeIf(p->paths.stream().anyMatch(other->!other.equals(p)&&p.startsWith(other)));return List.copyOf(unique);}
}
